# ---- what they come to -----------------------------------------------------------
stat, spread, span, clear, errors = chain.stat, chain.spread, chain.span, chain.clear, chain.errors
TABLES = {"RUN": RUN, "GATE": GATE, "GIVEN": GIVEN}


def cells(table, w, kind, row, draw):
    """A run's cell for each of the five networks: from this file's tables, or for a row
    with training's range from pta_board_chain.py's, which are the same runs."""
    core, rng, images = row
    if rng == TRAIN:
        return getattr(chain, table)[w][kind][(core, images, draw)]
    return TABLES[table][w][kind][(core, rng, images, draw)]


def shift(w, kind, row, n):
    """The shift of a network's last converter in a row: its step is two to that power."""
    _, rng, images = row
    return chain.FULL[w][kind][n][0] if rng == TRAIN else SHIFT[w][kind][(rng, images)][n]


def peak(w, kind, n, images):
    """The largest a network's declared reference is, which no range moves."""
    return chain.peak(w, kind, n, images)


def runs(w, kind, row, draw):
    return [c[0] for c in cells("RUN", w, kind, row, draw)]


def agrees(w, kind, row, draw):
    return [c[HOST] for c in cells("RUN", w, kind, row, draw)]


def declares(w, kind, row, draw):
    return [c[DECLARED_CLASS] for c in cells("RUN", w, kind, row, draw)]


def partner(row, draw):
    """The row and draw a row is read over: its own row with training's range for a fitted
    one, and the fitted one for one with a bit spare, each of its draw.  With training's
    range it is pta_board_chain.py's: the format alone of its draw for the tile as
    budgeted, and the plan's draw for the format alone."""
    core, rng, images = row
    if rng == SPARE:
        return (core, FIT, images), draw
    if rng == FIT:
        return (core, TRAIN, images), draw
    return (("format", TRAIN, images), PLAN) if core == "format" else (("format", TRAIN, images), draw)


def diffs(w, kind, row, draw):
    return [p - x for p, x in zip(runs(w, kind, *partner(row, draw)), runs(w, kind, row, draw))]


def acc(w, kind, row, draw):
    return stat(runs(w, kind, row, draw))


def adds(w, kind, row, draw):
    return stat(diffs(w, kind, row, draw))


def by_net(w, kind, row, what=diffs):
    return [sum(what(w, kind, row, d)[i] for d in DRAWS) / len(DRAWS) for i in range(SEEDS)]


def by_draw(w, kind, row, what=diffs):
    return [sum(what(w, kind, row, d)) / SEEDS for d in DRAWS]


def over(w, kind, row):
    """What a row adds over the row it is read over, over the draws."""
    return stat(by_net(w, kind, row))


def draw_sd(w, kind, row):
    return spread(by_draw(w, kind, row))


def right(w, kind, row):
    return stat(by_net(w, kind, row, runs))


def right_sd(w, kind, row):
    return spread(by_draw(w, kind, row, runs))


def agree(w, kind, row, what=agrees):
    return stat(by_net(w, kind, row, what))


def agree_sd(w, kind, row, what=agrees):
    return spread(by_draw(w, kind, row, what))


def declared(w, kind, row):
    """How often the tile's class is its declared reference's in a row, over the draws."""
    return agree(w, kind, row, declares)


def each_run(table, w, kind, row):
    """A table's cell for each of a row's 25 runs, network by network and then draw by draw."""
    return [cells(table, w, kind, row, d)[n] for n in range(SEEDS) for d in DRAWS]


def least(w, kind, row, which=HOST):
    return min(c[which] for c in each_run("RUN", w, kind, row))


def at_bar(w, kind, row, bar=GATE_CLASS, which=HOST):
    return sum(c[which] >= bar for c in each_run("RUN", w, kind, row))


def at_gate(w, kind, row):
    """The runs of 25 that pass the gate on the class: the declared reference's, on 99.5%."""
    return at_bar(w, kind, row, GATE_CLASS, DECLARED_CLASS)


def error(w, kind, row, table="GATE"):
    """A row's error over its runs, percent: its rms over the reference's rms, over the
    largest the reference is, and its largest over that, each a mean."""
    got = each_run(table, w, kind, row)
    return tuple(100 * sum(c[n] for c in got) / len(got) for n in range(3))


def most(w, kind, row, table="GATE"):
    return 100 * max(c[2] for c in each_run(table, w, kind, row))


def within(w, kind, row, table="GATE"):
    got = each_run(table, w, kind, row)
    return tuple(sum(100 * c[n] <= bar for c in got) for n, bar in ((0, GATE_RMS), (1, GATE_RMS), (2, GATE_MAX)))


def larger(w, kind, row):
    """For each network, by how many bits its step in a row is over the one training's
    rule gave."""
    return [shift(w, kind, row, n) - chain.FULL[w][kind][n][0] for n in range(SEEDS)]


def past(w, kind, row):
    """The converter's range over a row's runs: the runs with a sum past it; the most sums
    past it in a run; the most the largest error is, percent of the largest the reference
    is, in the runs with none past it and in the runs with some; the runs whose step is
    larger than training's; and by how many bits at the most."""
    pairs = list(zip(each_run("RUN", w, kind, row), each_run("GATE", w, kind, row)))
    some = [(r[2], 100 * g[2]) for r, g in pairs if r[2] > 0]
    none = [100 * g[2] for r, g in pairs if r[2] == 0]
    more = larger(w, kind, row)
    return (len(some), max((s for s, _ in some), default=0), max(none, default=0.0), max((z for _, z in some), default=0.0),
            len(DRAWS) * sum(b != 0 for b in more), max(more + [0]))


def sums(row):
    return OUTPUTS * row[2]


def in_steps(w, kind, row, n, draw, which=1):
    """A run's error in steps of its own converter: its rms (which=1) or its largest (2)."""
    return cells("GATE", w, kind, row, draw)[n][which] * peak(w, kind, n, row[2]) / 2 ** shift(w, kind, row, n)


def steps(w, kind, row, which=1):
    """A row's rms error against its declared format, in steps of the row's own converter:
    a mean over its 25 runs.  With which=2, its largest error."""
    xs = [in_steps(w, kind, row, n, d, which) for n in range(SEEDS) for d in DRAWS]
    return sum(xs) / len(xs)


def of_top(w, kind, row, which=1):
    """The same as a share of the converter's full scale, percent."""
    return 100 * steps(w, kind, row, which) / TOP


def top_within(w, kind, row):
    """The runs whose rms is within the gate's 1.0% of the converter's full scale, and
    whose largest error is within its 2.0%."""
    return tuple(sum(100 * in_steps(w, kind, row, n, d, which) / TOP <= bar for n in range(SEEDS) for d in DRAWS)
                 for which, bar in ((1, GATE_RMS), (2, GATE_MAX)))


def sigmas(w, kind, row):
    got = each_run("GATE", w, kind, row)
    return sum(c[2] / c[1] for c in got) / len(got)


def reach(w, kind, row):
    """For each network, the largest its declared reference is over the full scale of the
    converter the row gives it."""
    return [peak(w, kind, n, row[2]) / (TOP * 2 ** shift(w, kind, row, n)) for n in range(SEEDS)]


def total(what, row, n=None):
    """A count over the three data sets and both kinds: 150 runs."""
    return sum(what(w, k, row) if n is None else what(w, k, row)[n] for w in WORKLOADS for k in KINDS)


def every(what, row, kinds=KINDS):
    return span([what(w, k, row) for w in WORKLOADS for k in kinds])


def moved(rng, images):
    """The networks whose step, fitted or with a bit spare, is not the one training's rule
    gave: (data set, kind, network, bits more)."""
    return [(w, k, n, b) for w in WORKLOADS for k in KINDS
            for n, b in enumerate(larger(w, k, ("budget", rng, images))) if b != 0]


def cost(w, kind, n, images, rng=FIT, under=TRAIN):
    """What a larger step costs a network as budgeted: its rms error with it over its rms
    error with the smaller, a mean over the draws.  Both are against one reference, so it
    is a ratio of errors in the sum's own units."""
    a, b = ("budget", rng, images), ("budget", under, images)
    return sum(cells("GATE", w, kind, a, d)[n][0] / cells("GATE", w, kind, b, d)[n][0] for d in DRAWS) / len(DRAWS)


def bit_costs(images=ALL):
    """What one bit more of range costs, for every network of the thirty: a bit spare
    over fitted."""
    return [cost(w, k, n, images, SPARE, FIT) for w in WORKLOADS for k in KINDS for n in range(SEEDS)]


def fit_costs(images=ALL):
    """And for the networks whose step fitting moved: fitted over training's."""
    return [cost(w, k, n, images) for w, k, n, _ in moved(FIT, images)]


def pm(x):
    return f"{x[0]:.2f} +-{x[1]:.2f}"


def dpm(x):
    return f"{x[0]:+.2f} +-{x[1]:.2f}"


def r2(x):
    return round(x[0], 2), round(x[1], 2)


def r3(x):
    return round(x[0], 3), round(x[1], 3)


def section(title):
    print(f"\n{title}\n{'-' * len(title)}")


def label(row):
    return NAME[row[0]] + ("" if row[1] == TRAIN else ", " + WAY[row[1]]) + (", a thousand" if row[2] == FEW else "")


def main():
    print("The first board's last layer, with a range that clips nothing.")
    print("pta_board_chain.py's networks and tile at version 2.  Five networks a kind, five draws.")
    heads = (f"  {'':<42}" + "".join(f"{w:>36}" for w in WORKLOADS) + "\n"
             + f"  {'':<42}" + "".join(f"{k:>18}" for w in WORKLOADS for k in KINDS))

    section("1. A row over its five draws: how often right, and what it adds over the row it is read over")
    for w in WORKLOADS:
        print(f"  {w:<44}{'before, right':>24}{'and adds':>24}{'reference, right':>24}{'and adds':>24}")
        for row in BASES:
            print(f"    {label(row):<42}" + "".join(f"{right(w, k, row)[0]:>10.3f} +-{right(w, k, row)[1]:.3f} {right_sd(w, k, row):>5.3f}"
                                               f"{over(w, k, row)[0]:>+10.3f} +-{over(w, k, row)[1]:.3f} {draw_sd(w, k, row):>5.3f}" for k in KINDS))

    section("2. The class the tile gives against the class its declared reference gives, percent; and the runs of 25 at 99.5% or more")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<40}" + "".join(f"{declared(w, k, row)[0]:>9.3f} {at_gate(w, k, row):>2d} of 25" for w in WORKLOADS for k in KINDS))

    section("3. The last layer's rms error against its declared format, percent of the reference's rms")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<40}" + "".join(f"{error(w, k, row)[0]:>18.3f}" for w in WORKLOADS for k in KINDS))
    section("4. The same in steps of the row's own converter, and as a share of its full scale, percent")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<40}" + "".join(f"{steps(w, k, row):>10.3f}{of_top(w, k, row):>8.3f}" for w in WORKLOADS for k in KINDS))
    section("5. The largest error: a mean over the runs and the most of any, percent of the largest the reference is")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<40}" + "".join(f"{error(w, k, row)[2]:>10.3f}{most(w, k, row):>8.3f}" for w in WORKLOADS for k in KINDS))
    section("6. Runs of 25 within the gate: 1.0% rms of the reference's rms, of its largest, of the converter's full scale; 2.0% largest of the reference's largest, of full scale")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<40}" + "".join(f"{' '.join(str(n) for n in within(w, k, row)[:2] + top_within(w, k, row)[:1] + within(w, k, row)[2:] + top_within(w, k, row)[1:]):>18}"
                                                for w in WORKLOADS for k in KINDS))
    section("7. The converter's range: runs with a sum past it, the most in a run, runs with a larger step than training's, and bits more at the most")
    print(heads)
    for row in BASES:
        print(f"    {label(row):<40}" + "".join(f"{past(w, k, row)[0]:>5d}{past(w, k, row)[1]:>5d}{past(w, k, row)[4]:>5d}{past(w, k, row)[5]:>3d}" for w in WORKLOADS for k in KINDS))
    section("8. What a larger step costs a network as budgeted: its rms error over its rms error with the smaller")
    for images in (ALL, FEW):
        fc, bc = fit_costs(images), bit_costs(images)
        print(f"    on {images:>6,} images: fitted over training's, the {len(fc)} networks it moved: {min(fc):.3f} to {max(fc):.3f}, mean {sum(fc) / len(fc):.3f};"
              f" a bit spare over fitted, all {len(bc)}: {min(bc):.3f} to {max(bc):.3f}, mean {sum(bc) / len(bc):.3f}")

    said = io.StringIO()
    with contextlib.redirect_stdout(said):
        findings()
    print(said.getvalue(), end="")
    checks(" ".join(said.getvalue().split()))


def pairs(what, fmt="{:.2f}"):
    """A figure for the networks trained before and for the reference on each data set."""
    v = [fmt.format(what(w, k)) for w in WORKLOADS for k in KINDS]
    return f"{v[0]} and {v[1]} on MNIST, {v[2]} and {v[3]} on Fashion-MNIST and {v[4]} and {v[5]} on the inverted set"


def lohi(what, row, fmt="{:.2f}", kinds=KINDS):
    lo, hi = every(what, row, kinds)
    return f"{fmt.format(lo)} to {fmt.format(hi)}"


def three(what, kind=REFERENCE, fmt="{:.2f}"):
    return ", ".join(fmt.format(what(w, kind)) for w in WORKLOADS[:2]) + " and " + fmt.format(what(WORKLOADS[2], kind))


def with_past(rows):
    """The runs with a sum past the converter's range, over some rows, the three data sets
    and both kinds."""
    return sum(past(w, k, row)[0] for row in rows for w in WORKLOADS for k in KINDS)


def all_largest(rows):
    """Every run's largest error in some rows, percent of the largest the reference is."""
    return [100 * g[2] for row in rows for w in WORKLOADS for k in KINDS for g in each_run("GATE", w, k, row)]


# What was written down before --gatefit had run any network (grx930's design note has the nine in
# full, timestamped 2026-10-13T13:38:57Z), for the reference networks on 10,000 images unless said:
# (number, what it said, how it came out).
def predictions():
    R, B = REFERENCE, BEFORE
    m, f, i = WORKLOADS
    FF, FB, SF, SB = ("format", FIT, ALL), ("budget", FIT, ALL), ("format", SPARE, ALL), ("budget", SPARE, ALL)
    TB, FBF, SBF = ("budget", TRAIN, ALL), ("budget", FIT, FEW), ("budget", SPARE, FEW)
    fitted = [(shift(w, k, FB, n), shift(w, k, SB, n), shift(w, k, FBF, n), shift(w, k, SBF, n)) for w in WORKLOADS for k in KINDS for n in range(SEEDS)]
    big = all_largest([FF])
    e = [error(w, R, FB)[0] for w in WORKLOADS]
    s = [error(w, R, SB)[0] for w in WORKLOADS]
    tops = [total(top_within, row, 0) for row in (TB, FB, SB)]
    largest = [error(w, k, FB)[2] for w in WORKLOADS for k in KINDS]
    d, df = [declared(w, R, FB)[0] for w in WORKLOADS], [declared(w, R, FBF)[0] for w in WORKLOADS]
    ds = [declared(w, R, SB)[0] for w in WORKLOADS]
    add, more = [over(w, R, FB) for w in WORKLOADS], [over(w, R, SB) for w in WORKLOADS]
    return (
        (1, "fitted, the step grows for 5 networks of 30 on 10,000 images and for 2 on a thousand, by a bit, and with a bit spare every step is one bit more than fitted",
         [len(moved(FIT, ALL)), len(moved(FIT, FEW))] == [5, 2] and all(b == 1 for _, _, _, b in moved(FIT, ALL) + moved(FIT, FEW))
         and all(sa == fa + 1 and sf == ff + 1 for fa, sa, ff, sf in fitted)),
        (2, "the format alone, fitted, has a largest error of 0.4 to 0.85% in every run, all 150 within 2.0%, and 90 to 100 runs within 1.0% of the reference's rms",
         0.4 <= min(big) and max(big) <= 0.85 and total(within, FF, 2) == 150 and 90 <= total(within, FF, 0) <= 100),
        (3, "a step a bit larger costs 1.3 to 1.5 times in rms; fitted it is 4.6 to 5.0, 5.1 to 5.6 and 4.18% of the reference's rms, and with a bit spare 6.3 to 7.1, 7.0 to 8.0 and 5.6 to 6.2%",
         all(1.3 <= c <= 1.5 for c in fit_costs()) and 4.6 <= e[0] <= 5.0 and 5.1 <= e[1] <= 5.6 and round(e[2], 2) == 4.18
         and 6.3 <= s[0] <= 7.1 and 7.0 <= s[1] <= 8.0 and 5.6 <= s[2] <= 6.2),
        (4, "the runs of 150 within 1.0% of the converter's full scale are 20, then 38 to 46, then 135 to 150; within 1.0% of the reference's rms, none",
         tops[0] == 20 and 38 <= tops[1] <= 46 and 135 <= tops[2] <= 150 and all(total(within, row, 0) == 0 for row in (TB, FB, SB))),
        (5, "as budgeted and fitted the largest error is 7.3 to 9.0% of the largest the reference is on every set and kind, under 12.5% in every run, and within 2.0% in none",
         all(7.3 <= x <= 9.0 for x in largest) and max(all_largest([FB])) < 12.5 and total(within, FB, 2) == 0 and total(within, SB, 2) == 0),
        (6, "as budgeted and fitted 5 to 40 runs of 150 still have a sum past the range, and with a bit spare none",
         5 <= with_past([FB]) <= 40 and with_past([SB]) == 0),
        (7, "fitted, the class is the declared reference's on 99.52 to 99.59, 96.1 to 96.6 and 99.23%; on a thousand 99.49 with 13 runs at 99.5%, 96.5 to 96.85, and 99.10 with 1",
         99.52 <= d[0] <= 99.59 and 96.1 <= d[1] <= 96.6 and round(d[2], 2) == 99.23 and round(df[0], 2) == 99.49 and at_gate(m, R, FBF) == 13
         and 96.5 <= df[1] <= 96.85 and round(df[2], 2) == 99.10 and at_gate(i, R, FBF) == 1),
        (8, "with a bit spare it is 99.33 to 99.46, 94.6 to 95.5 and 98.82 to 98.97%, and on a thousand 3 to 9 runs of 25 are at 99.5% on MNIST",
         99.33 <= ds[0] <= 99.46 and 94.6 <= ds[1] <= 95.5 and 98.82 <= ds[2] <= 98.97 and 3 <= at_gate(m, R, SBF) <= 9),
        (9, "fitted adds 0.00 to 0.03, 0.02 to 0.15 and nothing, clear on none; a bit spare adds 0.00 to 0.06, 0.08 to 0.30 and 0.00 to 0.08 more, clear on Fashion-MNIST alone",
         0 <= add[0][0] <= 0.03 and 0.02 <= add[1][0] <= 0.15 and add[2] == (0.0, 0.0) and not any(clear(x) for x in add)
         and 0 <= more[0][0] <= 0.06 and 0.08 <= more[1][0] <= 0.30 and 0 <= more[2][0] <= 0.08 and [clear(x) for x in more] == [False, True, False]),
    )


def findings():
    m, f, i = WORKLOADS
    R, B = REFERENCE, BEFORE
    TF, TB, FF, FB, SF, SB = (("format", TRAIN, ALL), ("budget", TRAIN, ALL), ("format", FIT, ALL), ("budget", FIT, ALL),
                              ("format", SPARE, ALL), ("budget", SPARE, ALL))
    TFF, TBF, FFF, FBF, SFF, SBF = (("format", TRAIN, FEW), ("budget", TRAIN, FEW), ("format", FIT, FEW), ("budget", FIT, FEW),
                                    ("format", SPARE, FEW), ("budget", SPARE, FEW))
    rms_rms = lambda w, k, row: error(w, k, row)[0]
    max_peak = lambda w, k, row: error(w, k, row)[2]
    fc, bc = fit_costs(), bit_costs()
    print()
    print("What this says, eight readings.  All of it is a stand-in classifier's, in a model.")
    print()
    print("  1. FITTED, NO SUM IS PAST THE RANGE, WITH THE NOISE OR WITHOUT IT.  Not one, in any of the 600 fitted")
    print(f"     runs, where {with_past([TF, TB, TFF, TBF])} of the same 600 with training's range had one.  Fitting moves the step of {len(moved(FIT, ALL))} networks of 30 on")
    print(f"     10,000 images and of {len(moved(FIT, FEW))} on the first thousand, by one bit each, and makes none smaller: the others'")
    print("     runs are the runs they were, figure for figure.")
    print()
    print("  2. THE FORMAT ALONE THEN MEETS THE 2.0% IN EVERY RUN.  Its largest error is")
    print(f"     {min(all_largest([FF, FFF])):.2f} to {max(all_largest([FF, FFF])):.2f}% of the largest the reference is, where it was as much as {max(all_largest([TF, TFF])):.2f}%.  All 300 runs")
    print(f"     are within {GATE_MAX:.1f}%, where {total(within, TF, 2) + total(within, TFF, 2)} were.  It is half a step of a converter at the most.")
    print()
    print("  3. AS BUDGETED THE LARGEST ERROR IS THEN THE NOISE'S ALONE, AND IS STILL NOT WITHIN 2.0%.  Its mean over")
    print(f"     a set's runs is {lohi(max_peak, FB, '{:.1f}')}% on 10,000 images, where it was {lohi(max_peak, TB, '{:.1f}')}%, and the most in any run is")
    print(f"     {max(all_largest([FB])):.1f}%, where it was {max(all_largest([TB])):.1f}%.  On the first thousand it is {lohi(max_peak, FBF, '{:.1f}')}%.  No run of the 300 is within {GATE_MAX:.1f}%:")
    print(f"     the least is {min(all_largest([FB, FBF])):.1f}%.")
    print()
    print("  4. WHAT IT COSTS IS A FIFTH MORE ERROR, FOR THE NETWORKS IT MOVES.  A network whose step grew by a bit")
    print(f"     has {min(fc):.2f} to {max(fc):.2f} times the rms error it had, in the sum's own units.  So a set's rms, as a share of the")
    print(f"     reference's rms, goes from {rms_rms(m, R, TB):.2f} to {rms_rms(m, R, FB):.2f}% for MNIST's reference networks, of which one moves; from")
    print(f"     {rms_rms(f, R, TB):.2f} to {rms_rms(f, R, FB):.2f}% for Fashion-MNIST's, two; and from {rms_rms(i, B, TB):.2f} to {rms_rms(i, B, FB):.2f}% for the inverted set's networks trained")
    print("     before, two.  The other three stay what they were.")
    print()
    print("  5. A BIT SPARE COSTS A QUARTER MORE AGAIN, AND EVERY NETWORK PAYS IT.  With one more bit of range than")
    print(f"     fits, a network has {min(bc):.2f} to {max(bc):.2f} times its fitted rms error, {sum(bc) / len(bc):.2f} in the mean of the thirty.  The rms is then")
    print(f"     {lohi(rms_rms, SB, '{:.1f}')}% of the reference's rms, and the largest error {lohi(max_peak, SB, '{:.1f}')}% of the largest the reference is.")
    print()
    print("  6. AND AS A SHARE OF FULL SCALE IT READS BETTER.  The same error, in steps of the converter each row")
    print(f"     has: {lohi(steps, TB)} with training's range, {lohi(steps, FB)} fitted and {lohi(steps, SB)} with a bit spare.  Of the 150 runs")
    print(f"     as budgeted, {total(top_within, TB, 0)}, {total(top_within, FB, 0)} and {total(top_within, SB, 0)} are within {GATE_RMS:.1f}% of the converter's full scale, and {total(within, TB, 0)}, {total(within, FB, 0)} and {total(within, SB, 0)} within {GATE_RMS:.1f}% of the")
    print("     reference's rms.  A bound that is a share of full scale is met by declaring a larger full scale.")
    print()
    print("  7. THE CLASS.  As budgeted and fitted the reference networks give their declared reference's class on")
    print(f"     {three(lambda w, k: declared(w, k, FB)[0])}% of 10,000 images, where they gave it on {three(lambda w, k: declared(w, k, TB)[0])}%.  On the first")
    print(f"     thousand it is {three(lambda w, k: declared(w, k, FBF)[0])}%, with {three(lambda w, k: at_gate(w, k, FBF), fmt='{:d}')} runs of 25 at {GATE_CLASS}%: on MNIST and on the")
    print("     inverted set no reference network moves there, and those are the runs they were.  With a bit spare it is")
    print(f"     {three(lambda w, k: declared(w, k, SB)[0])}% of 10,000, and {three(lambda w, k: at_gate(w, k, SBF), fmt='{:d}')} runs on the first thousand.  The format alone with a bit")
    print(f"     spare is at {three(lambda w, k: declared(w, k, SF)[0])}%: a converter that rounds twice as coarsely moves the class by itself.")
    print()
    print("  8. IN POINTS OF ACCURACY.  Fitting loses the reference networks")
    print(f"     {three(lambda w, k: dpm(over(w, k, FB)), R, '{}')}, clear on none.  A bit spare loses them")
    print(f"     {three(lambda w, k: dpm(over(w, k, SB)), R, '{}')} more: clear on Fashion-MNIST and on the inverted set.")
    print()
    got = predictions()
    print(f"What it was predicted to say.  Nine, written before the option had run a network: {sum(ok for _, _, ok in got)} right.")
    for n, what, ok in got:
        print(f"  {n}. {'right' if ok else 'WRONG'}: {what}")


def checks(said):
    """Every claim above, as an assert.  `said` is the readings as printed, on one line."""
    m, f, i = WORKLOADS
    R, B = REFERENCE, BEFORE
    each = [(w, k) for w in WORKLOADS for k in KINDS]
    new = [row for row in BASES if row[1] != TRAIN]
    keys = [row + (d,) for d in DRAWS for row in BASES]
    held = [row + (d,) for d in DRAWS for row in new]
    assert len(keys) == 60 and len(held) == 40 and set(SHARE) == {FIT, SPARE} and (SHARE[FIT], SHARE[SPARE]) == (1.0, 0.5)
    assert set(RUN) == set(GATE) == set(GIVEN) == set(SHIFT) == set(WORKLOADS)
    assert set(PRINTED_ROWS) == set(PRINTED_OVER) == set(PRINTED_AGREE) == set(PRINTED_DECLARED) == set(PRINTED_GATE) == set(PRINTED_GIVEN) == set(PRINTED_RANGE) == set(WORKLOADS)
    for w, k in each:
        assert set(RUN[w][k]) == set(GATE[w][k]) == set(GIVEN[w][k]) == set(held), (w, k)
        assert set(SHIFT[w][k]) == {(rng, images) for rng in (FIT, SPARE) for images in (ALL, FEW)}, (w, k)
        assert all(len(SHIFT[w][k][x]) == SEEDS for x in SHIFT[w][k])
        for key in held:
            assert len(RUN[w][k][key]) == len(GATE[w][k][key]) == len(GIVEN[w][k][key]) == SEEDS
            for (a, g, s, d), (x, y, z), (e, u, v) in zip(RUN[w][k][key], GATE[w][k][key], GIVEN[w][k][key]):
                assert 0 <= a <= 100 and 50 < g <= 100 and 50 < d <= 100 and 0 <= s <= sums(key[:3]) / 100, (w, k, key)
                assert 0 < y <= z and 0 < x and 0 < u <= v and e > 0.02, (w, k, key)

    # 0. The figures are grx930's.  The seven tables its harness printed, every cell, from the
    #    networks' own figures: a row with training's range from pta_board_chain.py's.
    def same(a, b, tol=0.0051):
        return abs(a[0] - b[0]) < tol and abs(a[1] - b[1]) < tol

    def same3(g, p, tol=0.00051):
        return len(g) == len(p) and all(abs(a - b) < tol for a, b in zip(g, p))

    count = 0
    for w in WORKLOADS:
        assert set(PRINTED_ROWS[w]) == set(keys)
        assert set(PRINTED_OVER[w]) == set(PRINTED_AGREE[w]) == set(PRINTED_DECLARED[w]) == set(PRINTED_GATE[w]) == set(PRINTED_GIVEN[w]) == set(PRINTED_RANGE[w]) == set(BASES)
        for key in keys:
            row, d = key[:3], key[3]
            got = (acc(w, B, row, d), adds(w, B, row, d), acc(w, R, row, d), adds(w, R, row, d))
            assert len(PRINTED_ROWS[w][key]) == 4 and all(same(a, b) for a, b in zip(got, PRINTED_ROWS[w][key])), (w, key)
            count += 4
        for row in BASES:
            got = [x for k in KINDS for x in (right(w, k, row) + (right_sd(w, k, row),), over(w, k, row) + (draw_sd(w, k, row),))]
            assert len(PRINTED_OVER[w][row]) == 4 and all(same3(g, p) for g, p in zip(got, PRINTED_OVER[w][row])), (w, row)
            count += 12
            for k, p in zip(KINDS, PRINTED_AGREE[w][row]):
                assert same3(agree(w, k, row) + (agree_sd(w, k, row),), p[:3]) and abs(least(w, k, row) - p[3]) < 1e-9, (w, k, row)
                assert (at_bar(w, k, row), 25) == p[4:], (w, k, row)
                count += 6
            for k, p in zip(KINDS, PRINTED_DECLARED[w][row]):
                assert same3(agree(w, k, row, declares) + (agree_sd(w, k, row, declares),), p[:3]), (w, k, row)
                assert abs(least(w, k, row, DECLARED_CLASS) - p[3]) < 1e-9 and (at_gate(w, k, row), 25) == p[4:6], (w, k, row)
                assert len(p) == 7 and abs(chain.declared_right(w, k, row[2]) - p[6]) < 0.00051, (w, k, row)
                count += 7
            for table, printed in (("GATE", PRINTED_GATE), ("GIVEN", PRINTED_GIVEN)):
                for k, p in zip(KINDS, printed[w][row]):
                    assert same3(error(w, k, row, table) + (most(w, k, row, table),), p[:4]) and within(w, k, row, table) == p[4:], (w, k, row, table)
                    count += 7
            for k, p in zip(KINDS, PRINTED_RANGE[w][row]):
                some, top, none, where_some, steps_moved, bits = past(w, k, row)
                assert (some, 25, top, sums(row)) == p[:4] and same3((none, where_some), p[4:6]) and (steps_moved, bits) == p[6:], (w, k, row)
                count += 8
    assert count == 3 * (60 * 4 + 12 * (12 + 12 + 14 + 14 + 14 + 16)) == 3672
    #    And a row with training's range is the row pta_board_chain.py's harness printed: its tables'
    #    cells are that file's, figure for figure.
    for w in WORKLOADS:
        for core, _ in CORES:
            for images in (ALL, FEW):
                here, there = (core, TRAIN, images), (core, images)
                assert PRINTED_OVER[w][here] == chain.PRINTED_OVER[w][there] and PRINTED_AGREE[w][here] == chain.PRINTED_AGREE[w][there]
                assert PRINTED_DECLARED[w][here] == chain.PRINTED_DECLARED[w][there] and PRINTED_GATE[w][here] == chain.PRINTED_GATE[w][there]
                assert PRINTED_GIVEN[w][here] == chain.PRINTED_GIVEN[w][there]
                assert all(p[:6] == q and p[6:] == (0, 0) for p, q in zip(PRINTED_RANGE[w][here], chain.PRINTED_RANGE[w][there]))
                for d in DRAWS:
                    assert PRINTED_ROWS[w][here + (d,)] == chain.PRINTED_ROWS[w][there + (d,)]

    TF, TB, FF, FB, SF, SB = (("format", TRAIN, ALL), ("budget", TRAIN, ALL), ("format", FIT, ALL), ("budget", FIT, ALL),
                              ("format", SPARE, ALL), ("budget", SPARE, ALL))
    TFF, TBF, FFF, FBF, SFF, SBF = (("format", TRAIN, FEW), ("budget", TRAIN, FEW), ("format", FIT, FEW), ("budget", FIT, FEW),
                                    ("format", SPARE, FEW), ("budget", SPARE, FEW))
    fitted, spare, trained = (FF, FB, FFF, FBF), (SF, SB, SFF, SBF), (TF, TB, TFF, TBF)

    def six(what, digits=2):
        return [round(what(w, k), digits) for w, k in each]

    rms_rms = lambda row: (lambda w, k: error(w, k, row)[0])
    max_peak = lambda row: (lambda w, k: error(w, k, row)[2])
    # The rule, held to each network: a fitted shift is the smallest at which the largest its declared
    # reference is, is within the converter's 127 codes, and with a bit spare within 63.  It is the
    # same for the format alone and for the tile as budgeted, since no draw moves a reference.
    for w, k in each:
        for images in (ALL, FEW):
            for rng, lim in ((FIT, TOP), (SPARE, TOP // 2)):
                for n in range(SEEDS):
                    s, p = shift(w, k, ("budget", rng, images), n), peak(w, k, n, images)
                    assert math.floor(p / 2 ** s + 0.5) <= lim < math.floor(p / 2 ** (s - 1) + 0.5), (w, k, images, rng, n)
                    assert s == shift(w, k, ("format", rng, images), n)
    #    The format alone is one row whatever the draw, at every range.
    assert all(cells(t, w, k, row, d) == cells(t, w, k, row, PLAN) for t in TABLES for w, k in each for row in (FF, FFF, SF, SFF) for d in DRAWS)
    assert [partner(row, 3) for row in (TF, TB, FB, SB, SFF)] == [(TF, PLAN), (TF, 3), (TB, 3), (FB, 3), (FFF, 3)]

    # 1. Reading 1.  Fitted, no sum is past the range.
    assert with_past(fitted) == 0 and with_past(spare) == 0 and with_past(trained) == 70
    assert [with_past([row]) for row in trained] == [25, 25, 10, 10] and sum(len(each_run("RUN", w, k, row)) for row in fitted for w, k in each) == 600
    assert [(w, k, n, b) for w, k, n, b in moved(FIT, ALL)] == [(m, R, 1, 1), (f, R, 1, 1), (f, R, 4, 1), (i, B, 3, 1), (i, B, 4, 1)]
    assert [(w, k, n, b) for w, k, n, b in moved(FIT, FEW)] == [(f, R, 1, 1), (i, B, 3, 1)]
    assert all(b >= 0 for w, k in each for row in fitted + spare for b in larger(w, k, row))
    #    The networks fitting moves are the ones whose reference reached past training's range.
    for images, row in ((ALL, FB), (FEW, FBF)):
        assert [(w, k, n) for w, k, n, _ in moved(FIT, images)] == [(w, k, n) for w, k in each for n in range(SEEDS) if chain.reach(w, k, images)[n] > 1]
    #    A fitted run of a network it does not move is the run with training's range, figure for figure.
    for w, k in each:
        for row, under in ((FF, TF), (FB, TB), (FFF, TFF), (FBF, TBF)):
            for n in range(SEEDS):
                if larger(w, k, row)[n] == 0:
                    assert all(cells(t, w, k, row, d)[n] == cells(t, w, k, under, d)[n] for t in TABLES for d in DRAWS), (w, k, row, n)
    #    And with a bit spare every network has one bit more than fitted, and a reach of a half or less.
    assert all(shift(w, k, s, n) == shift(w, k, a, n) + 1 for w, k in each for s, a in zip(spare, fitted) for n in range(SEEDS))
    assert all(r <= 1 for w, k in each for row in fitted for r in reach(w, k, row)) and all(r <= 0.5 for w, k in each for row in spare for r in reach(w, k, row))
    assert [round(x, 2) for x in span([r for w, k in each for r in reach(w, k, FB)])] == [0.52, 0.97]

    # 2. Reading 2.  The format alone, fitted.
    assert [round(x, 2) for x in span(all_largest([FF, FFF]))] == [0.4, 0.77] and round(max(all_largest([TF, TFF])), 2) == 24.05
    assert total(within, FF, 2) + total(within, FFF, 2) == 300 and total(within, TF, 2) + total(within, TFF, 2) == 270
    #    Half a step at the most, in every fitted run and in every run with a bit spare: to the
    #    thousandth of a step that five printed digits leave.
    assert all(in_steps(w, k, row, n, d, 2) <= 0.501 for w, k in each for row in (FF, FFF, SF, SFF) for n in range(SEEDS) for d in DRAWS)
    assert [total(within, row, 0) for row in (TF, FF, SF)] == [120, 95, 0] and [total(within, row, 0) for row in (TFF, FFF, SFF)] == [115, 105, 0]

    # 3. Reading 3.  As budgeted, the largest error.
    assert six(max_peak(FB), 3) == [8.441, 7.947, 7.202, 7.915, 8.331, 7.44] and six(max_peak(TB), 3) == [8.441, 8.024, 7.202, 11.528, 8.598, 7.44]
    assert six(max_peak(FBF), 3) == [8.419, 7.685, 7.181, 7.604, 7.934, 7.162]
    assert [round(max(all_largest([row])), 2) for row in (FB, TB, FBF, SB)] == [9.7, 24.05, 10.16, 13.89]
    assert round(min(all_largest([FB, FBF])), 2) == 6.12 and total(within, FB, 2) + total(within, FBF, 2) == 0
    assert all(total(within, row, 2) == 0 and total(top_within, row, 1) == 0 for row in (FB, FBF, SB, SBF))
    #    In its own rms errors a run's largest is then where a tail sits, on every set: on all the images
    #    no set is more than an rms over where a Gaussian's is, where one was four and a half over.
    assert all(abs(sigmas(w, k, FB) - chain.tail(160000)) < 1 for w, k in each) and [round(x, 1) for x in every(sigmas, FB)] == [4.9, 5.8]
    assert [round(x, 1) for x in every(sigmas, TB)] == [5.0, 9.5]

    # 4. Reading 4.  What fitting costs the networks it moves.
    fc, bc = fit_costs(), bit_costs()
    assert len(fc) == 5 and [round(x, 3) for x in sorted(fc)] == [1.202, 1.203, 1.204, 1.218, 1.235] and [round(x, 3) for x in sorted(fit_costs(FEW))] == [1.209, 1.21]
    assert six(rms_rms(FB), 3) == [4.813, 4.638, 4.54, 5.047, 4.606, 4.183] and six(rms_rms(TB), 3) == [4.813, 4.463, 4.54, 4.674, 4.28, 4.183]
    assert [(w, k) for w, k in each if error(w, k, FB) != error(w, k, TB)] == [(m, R), (f, R), (i, B)]

    # 5. Reading 5.  A bit spare.
    assert len(bc) == 30 and [round(x, 2) for x in (min(bc), max(bc), sum(bc) / len(bc))] == [1.21, 1.38, 1.28]
    assert [round(x, 2) for x in (min(bit_costs(FEW)), max(bit_costs(FEW)), sum(bit_costs(FEW)) / 30)] == [1.2, 1.34, 1.27]
    assert six(rms_rms(SB), 3) == [6.046, 5.746, 5.749, 6.752, 6.049, 5.232] and six(max_peak(SB), 3) == [11.162, 10.227, 9.328, 10.548, 11.018, 9.628]
    #    Every network pays it, and none by less than a fifth.
    assert min(bc) > 1.2 and min(bit_costs(FEW)) > 1.2

    # 6. Reading 6.  As a share of full scale.
    assert [round(x, 2) for x in every(steps, TB) + every(steps, FB) + every(steps, SB)] == [1.43, 1.83, 1.15, 1.67, 0.77, 1.03]
    assert [round(x, 3) for x in every(of_top, TB) + every(of_top, FB) + every(of_top, SB)] == [1.127, 1.439, 0.906, 1.317, 0.605, 0.809]
    assert [total(top_within, row, 0) for row in (TB, FB, SB)] == [20, 45, 150] and [total(within, row, 0) for row in (TB, FB, SB)] == [0, 0, 0]
    assert [total(top_within, row, 0) for row in (TBF, FBF, SBF)] == [25, 35, 150] and [total(within, row, 1) for row in (TB, FB, SB)] == [0, 0, 0]
    #    The steps fall as the range grows, in every set, while the error in the sum's own units rises.
    assert all(steps(w, k, SB) < steps(w, k, FB) <= steps(w, k, TB) and error(w, k, SB)[0] > error(w, k, FB)[0] >= error(w, k, TB)[0] for w, k in each)

    # 7. Reading 7.  The class.
    assert six(lambda w, k: declared(w, k, FB)[0]) == [99.4, 99.55, 95.92, 96.2, 98.66, 99.23]
    assert six(lambda w, k: declared(w, k, TB)[0]) == [99.4, 99.59, 95.92, 96.78, 98.86, 99.23]
    assert six(lambda w, k: declared(w, k, FBF)[0]) == [99.25, 99.49, 96.01, 96.6, 98.65, 99.1] and [at_gate(w, k, FBF) for w, k in each] == [6, 13, 0, 0, 2, 1]
    assert six(lambda w, k: declared(w, k, SB)[0]) == [98.94, 99.26, 93.18, 93.2, 97.73, 98.83] and [at_gate(w, k, SBF) for w, k in each] == [0, 3, 0, 0, 0, 0]
    assert six(lambda w, k: declared(w, k, SF)[0]) == [99.38, 99.59, 95.7, 95.31, 98.54, 99.43] and [at_gate(w, k, FB) for w, k in each] == [2, 20, 0, 0, 0, 0]
    assert [at_gate(w, k, SB) for w, k in each] == [0, 1, 0, 0, 0, 0] and six(lambda w, k: declared(w, k, SBF)[0]) == [98.73, 99.22, 93.27, 94.11, 97.69, 98.57]
    #    On the first thousand no reference network of MNIST or of the inverted set moves.
    assert all(larger(w, R, FBF) == [0] * SEEDS for w in (m, i)) and all(declared(w, R, FBF) == declared(w, R, TBF) for w in (m, i))
    #    A wider range never has the tile give its declared reference's class more often, in the mean.
    assert all(declared(w, k, s)[0] < declared(w, k, a)[0] <= declared(w, k, t)[0] for w, k in each for t, a, s in ((TB, FB, SB), (TBF, FBF, SBF)))

    # 8. Reading 8.  In points of accuracy.
    assert [r2(over(w, R, FB)) for w in WORKLOADS] == [(0.02, 0.02), (0.12, 0.07), (0.0, 0.0)] and not any(clear(over(w, k, FB)) for w, k in each)
    assert [r2(over(w, R, SB)) for w in WORKLOADS] == [(0.1, 0.04), (0.94, 0.12), (0.17, 0.02)]
    assert [(w, k) for w, k in each if clear(over(w, k, SB))] == [(m, B), (f, B), (f, R), (i, B), (i, R)]
    assert [r2(over(w, B, SB)) for w in WORKLOADS] == [(0.18, 0.05), (0.75, 0.13), (0.44, 0.11)]

    # 9. The predictions: four of the nine as they were written.
    got = predictions()
    assert [n for n, _, ok in got if ok] == [1, 2, 4, 7] and [n for n, _, _ in got] == list(range(1, 10))
    #    The third: the cost of a bit was put at 1.3 to 1.5 times, and is 1.2.  The fifth: one set's mean
    #    is under the band, by a tenth of a point, and is the one no fit moved.  The sixth: no run has one.
    assert max(fc) < 1.3 and [x for x in six(max_peak(FB), 2) if not 7.3 <= x <= 9.0] == [7.2] and error(f, B, FB) == error(f, B, TB)
    #    The eighth: two sets of three are under their bands, Fashion-MNIST by a point and a half.  The
    #    ninth: right of fitting, and a bit spare costs three times what was written on Fashion-MNIST.
    assert [round(lo - declared(w, R, SB)[0], 2) for w, lo in zip(WORKLOADS, (99.33, 94.6, 98.82))] == [0.07, 1.4, -0.01]
    assert round(over(f, R, SB)[0] / 0.30, 1) == 3.1

    # 10. What the board plan (section 4.2 and B18) and the proposal to grxgpu (its section 10.5) quote
    #     of the reference networks, a column a data set.
    def col(what, digits=2):
        return [round(what(w), digits) for w in WORKLOADS]

    assert [col(lambda w: most(w, R, row)) for row in (TB, FB, SB)] == [[8.97, 24.05, 8.59], [8.97, 8.95, 8.59], [12.7, 11.84, 11.4]]
    assert [col(lambda w: error(w, R, row)[0]) for row in (TB, FB, SB)] == [[4.46, 4.67, 4.18], [4.64, 5.05, 4.18], [5.75, 6.75, 5.23]]
    assert [col(lambda w: steps(w, R, row)) for row in (TB, FB, SB)] == [[1.83, 1.43, 1.6], [1.67, 1.15, 1.6], [1.03, 0.77, 1.0]]
    assert [col(lambda w: of_top(w, R, row)) for row in (TB, FB, SB)] == [[1.44, 1.13, 1.26], [1.32, 0.91, 1.26], [0.81, 0.61, 0.79]]
    assert [col(lambda w: right(w, R, row)[0]) for row in (TB, FB, SB)] == [[96.97, 83.47, 95.19], [96.95, 83.35, 95.19], [96.85, 82.41, 95.02]]
    assert [[past(w, R, row)[1] for w in WORKLOADS] for row in (TB, FB, SB)] == [[27, 161, 0], [0, 0, 0], [0, 0, 0]]
    assert [[sum(b != 0 for b in larger(w, R, row)) for w in WORKLOADS] for row in (FB, SB)] == [[1, 2, 0], [5, 5, 5]]
    assert [[at_gate(w, R, row) for w in WORKLOADS] for row in (TBF, FBF, SBF)] == [[13, 0, 1], [13, 0, 1], [3, 0, 0]]
    #     A tile at version 2 with a fitted range, on the first thousand images of the reference networks.
    assert [round(x, 2) for x in every(lambda w, k, row: error(w, k, row)[0], FBF, (R,)) + every(lambda w, k, row: error(w, k, row)[1], FBF, (R,))
            + every(steps, FBF, (R,))] == [4.24, 4.85, 1.47, 1.72, 1.27, 1.78]
    assert round(sum(fc) / len(fc), 1) == 1.2 and round(sum(bc) / len(bc), 1) == 1.3

    # 11. And the readings say those figures, each in its place.
    for words in (
        "Not one, in any of the 600 fitted runs, where 70 of the same 600 with training's range had one.",
        "Fitting moves the step of 5 networks of 30 on 10,000 images and of 2 on the first thousand, by one bit each, and makes none smaller",
        "Its largest error is 0.40 to 0.77% of the largest the reference is, where it was as much as 24.05%. All 300 runs are within 2.0%, where 270 were.",
        "a set's runs is 7.2 to 8.4% on 10,000 images, where it was 7.2 to 11.5%, and the most in any run is 9.7%, where it was 24.1%.",
        "On the first thousand it is 7.2 to 8.4%. No run of the 300 is within 2.0%: the least is 6.1%.",
        "has 1.20 to 1.24 times the rms error it had, in the sum's own units.",
        "goes from 4.46 to 4.64% for MNIST's reference networks, of which one moves; from 4.67 to 5.05% for Fashion-MNIST's, two; and from 4.28 to 4.61% for the inverted set's networks trained before, two.",
        "a network has 1.21 to 1.38 times its fitted rms error, 1.28 in the mean of the thirty.",
        "The rms is then 5.2 to 6.8% of the reference's rms, and the largest error 9.3 to 11.2% of the largest the reference is.",
        "has: 1.43 to 1.83 with training's range, 1.15 to 1.67 fitted and 0.77 to 1.03 with a bit spare.",
        "as budgeted, 20, 45 and 150 are within 1.0% of the converter's full scale, and 0, 0 and 0 within 1.0% of the reference's rms.",
        "class on 99.55, 96.20 and 99.23% of 10,000 images, where they gave it on 99.59, 96.78 and 99.23%.",
        "thousand it is 99.49, 96.60 and 99.10%, with 13, 0 and 1 runs of 25 at 99.5%",
        "With a bit spare it is 99.26, 93.20 and 98.83% of 10,000, and 3, 0 and 0 runs on the first thousand.",
        "spare is at 99.59, 95.31 and 99.43%: a converter that rounds twice as coarsely moves the class by itself.",
        "Fitting loses the reference networks +0.02 +-0.02, +0.12 +-0.07 and +0.00 +-0.00, clear on none.",
        "A bit spare loses them +0.10 +-0.04, +0.94 +-0.12 and +0.17 +-0.02 more: clear on Fashion-MNIST and on the inverted set.",
        "Nine, written before the option had run a network: 4 right.",
    ):
        assert said.count(words) == 1, words
    assert said.count(" right: ") == 4 and said.count(" WRONG: ") == 5

    print()
    print("All checks pass.")


if __name__ == "__main__":
    main()
